using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using AshkanSocial.Core.Models;
using AshkanSocial.Core.Services;
using AshkanSocial.UI.Theme;
using AshkanSocial.UI.Controls;
namespace AshkanSocial.UI.Forms
{
 public partial class MainForm : Form
 {
  public void ShowSafetyCenter(){Page("Privacy & Safety Center");var u=Session.CurrentUser;content.Controls.Add(PageBanner("Privacy","Privacy & Safety","Control who can interact with you, manage blocked accounts and review safety tools.",150));var privacy=new CheckBox{Text="Private profile",Checked=u.PrivateProfile,Location=new Point(55,292),AutoSize=true,ForeColor=ThemeColors.TextPrimary,BackColor=ThemeColors.Background};privacy.CheckedChanged+=(s,e)=>{u.PrivateProfile=privacy.Checked;LogActivity("Changed profile privacy to "+(u.PrivateProfile?"private":"public"));db.Save();};content.Controls.Add(privacy);content.Controls.Add(Section("Blocked accounts ("+u.BlockedUserIds.Count+")",35,345));int y=385;foreach(var id in u.BlockedUserIds.ToList()){var x=db.Data.Users.FirstOrDefault(z=>z.Id==id);if(x==null)continue;var c=Card(y,65);c.Controls.Add(Txt(x.FullName+"  @"+x.Username,15,18,400));var un=Btn("Unblock",470,12,100);un.Click+=(s,e)=>{u.BlockedUserIds.Remove(x.Id);LogActivity("Unblocked @"+x.Username);db.Save();ShowSafetyCenter();};c.Controls.Add(un);content.Controls.Add(c);y+=77;}content.Controls.Add(Txt("Safety tools include blocking, reporting, privacy controls and an activity history.",35,y+15,760));}
  void Audit(string action,string targetType="System",string targetId=""){db.Data.AuditEntries.Add(new AuditEntry{Id=Guid.NewGuid().ToString(),ActorUserId=Session.CurrentUser.Id,Action=action,TargetType=targetType,TargetId=targetId,CreatedAt=DateTime.Now});}
  public void ShowSecurityCenter(){Page("Account Security");var u=Session.CurrentUser;content.Controls.Add(PageBanner("Protection","Account security","Manage recovery, local two-factor simulation and active device sessions.",205));content.Controls.Add(Section("Protection settings",35,292));var two=new CheckBox{Text="Two-factor authentication (local portfolio simulation)",Checked=u.TwoFactorEnabled,Location=new Point(55,330),AutoSize=true,ForeColor=ThemeColors.TextPrimary,BackColor=ThemeColors.Background};two.CheckedChanged+=(s,e)=>{u.TwoFactorEnabled=two.Checked;Audit("Changed two-factor authentication");db.Save();};content.Controls.Add(two);content.Controls.Add(Txt("Recovery email",35,385,250));var recovery=new TextBox{Text=u.RecoveryEmail??u.Email,Location=new Point(35,420),Width=330};content.Controls.Add(recovery);var save=Btn("Save recovery",380,417,145);save.Click+=(s,e)=>{u.RecoveryEmail=recovery.Text.Trim();Audit("Updated recovery email");db.Save();MessageBox.Show("Recovery settings saved.","Security");};content.Controls.Add(save);content.Controls.Add(Section("Active devices",35,485));int y=525;foreach(var ss in db.Data.Sessions.Where(x=>x.UserId==u.Id&&!x.Revoked).OrderByDescending(x=>x.LastActiveAt).ToList()){var c=Card(y,78);c.Controls.Add(Txt(ss.DeviceName+(ss.DeviceName==Environment.MachineName?"  ·  This device":""),15,12,430,24));c.Controls.Add(new Label{Text="Last active "+ss.LastActiveAt.ToString("MMM d, yyyy · HH:mm"),Location=new Point(15,42),AutoSize=true,ForeColor=ThemeColors.TextMuted});if(ss.DeviceName!=Environment.MachineName){var revoke=Btn("Revoke",c.Width-135,18,100);revoke.Anchor=AnchorStyles.Top|AnchorStyles.Right;revoke.Click+=(a,b)=>{ss.Revoked=true;Audit("Revoked device session","Session",ss.Id);db.Save();ShowSecurityCenter();};c.Controls.Add(revoke);}content.Controls.Add(c);y+=90;}}
  public void ShowAdminCenter(){Page("Admin & Moderation Center");if(!string.Equals(Session.CurrentUser.Role,"Admin",StringComparison.OrdinalIgnoreCase)){content.Controls.Add(PageBanner("Restricted","Admin Center","Administrator permission is required to access this workspace.",205));return;}var reports=db.Data.Reports.Where(x=>x.Status=="Open").OrderByDescending(x=>x.CreatedAt).ToList();content.Controls.Add(PageBanner("Governance","Admin & Moderation","Review reports, manage roles and inspect community governance activity.",158));content.Controls.Add(StatCard("Open reports",reports.Count.ToString(),35,292,180));content.Controls.Add(StatCard("Users",db.Data.Users.Count.ToString(),230,292,180));content.Controls.Add(Section("Open reports",35,420));int y=460;if(reports.Count==0){content.Controls.Add(Txt("No open reports. Community health looks good.",35,y,700));y+=55;}foreach(var r in reports){var c=Card(y,100);var reporter=db.Data.Users.FirstOrDefault(x=>x.Id==r.ReporterUserId);var target=db.Data.Users.FirstOrDefault(x=>x.Id==r.TargetUserId);c.Controls.Add(Txt((target==null?"Unknown target":"@"+target.Username)+" · "+r.Reason,15,12,520,28));c.Controls.Add(new Label{Text="Reported by "+(reporter==null?"unknown":"@"+reporter.Username)+" · "+r.CreatedAt.ToString("MMM d, HH:mm"),Location=new Point(15,48),AutoSize=true,ForeColor=ThemeColors.TextMuted});var resolve=Btn("Resolve",c.Width-135,25,100);resolve.Anchor=AnchorStyles.Top|AnchorStyles.Right;resolve.Click+=(a,b)=>{r.Status="Resolved";Audit("Resolved report","Report",r.Id);db.Save();ShowAdminCenter();};c.Controls.Add(resolve);content.Controls.Add(c);y+=112;}content.Controls.Add(Txt("User roles",35,y+10,300));y+=50;foreach(var u in db.Data.Users.OrderBy(x=>x.Username)){var c=Card(y,72);c.Controls.Add(Txt(u.FullName+"  @"+u.Username,15,12,430,24));var role=new ComboBox{Location=new Point(c.Width-210,18),Width=165,DropDownStyle=ComboBoxStyle.DropDownList,Anchor=AnchorStyles.Top|AnchorStyles.Right};role.Items.AddRange(new object[]{"Member","Moderator","Admin"});role.SelectedItem=string.IsNullOrWhiteSpace(u.Role)?"Member":u.Role;role.SelectedIndexChanged+=(a,b)=>{u.Role=role.SelectedItem.ToString();Audit("Changed role to "+u.Role,"User",u.Id);db.Save();};c.Controls.Add(role);content.Controls.Add(c);y+=84;}content.Controls.Add(Txt("Recent audit trail",35,y+15,300));y+=55;foreach(var a in db.Data.AuditEntries.OrderByDescending(x=>x.CreatedAt).Take(20)){var actor=db.Data.Users.FirstOrDefault(x=>x.Id==a.ActorUserId);var c=Card(y,62);c.Controls.Add(Txt((actor==null?"System":"@"+actor.Username)+" · "+a.Action,15,10,650,24));c.Controls.Add(new Label{Text=a.CreatedAt.ToString("MMM d, yyyy · HH:mm")+" · "+a.TargetType,Location=new Point(15,36),AutoSize=true,ForeColor=ThemeColors.TextMuted});content.Controls.Add(c);y+=72;}}
 }
}
